"""Render the archive introduction without adding a Work-menu card."""
import argparse,html,json,re
from pathlib import Path
from public_routes import editorial_url
ROOT=Path(__file__).resolve().parents[1];PROFILE=ROOT/'pages/profile';BODY_ID='noreut-galchi-album'
def render():
 catalog=json.loads((PROFILE/'data/message-bodies.json').read_text());b=next(x for x in catalog['bodies'] if x['body_id']==BODY_ID)
 visit=json.loads((PROFILE/'data/noreut-visit.json').read_text());place=visit['place']
 url=editorial_url(BODY_ID);og=url+'assets/og.png';title=visit['introductionTitle'];desc=visit['description'];e=html.escape
 def prose(value):return re.sub(r'([,.])\s+',r'\1<br>',e(value))
 graph={'@context':'https://schema.org','@graph':[{'@type':'Place','@id':place['id'],'name':place['name'],'hasMap':place['mapUrl']},{'@type':'WebPage','@id':url,'url':url,'name':title,'description':desc,'inLanguage':'ko','mainEntity':{'@id':b['canonical_url']+'/cinema/#work'},'author':{'@id':'https://mirinaeman.com/profile/#person'}},{'@type':'Person','@id':'https://mirinaeman.com/profile/#person','name':'미리내맨','url':'https://mirinaeman.com/profile/'},{'@type':'CreativeWork','@id':b['canonical_url']+'/cinema/#work','name':b['title'],'url':b['canonical_url'],'creator':{'@id':'https://mirinaeman.com/profile/#person'},'about':{'@id':place['id']}},{'@type':'MusicRecording','@id':b['canonical_url']+'/#recording','name':b['title'],'byArtist':{'@id':'https://mirinaeman.com/profile/#person'},'url':b['canonical_url']}]}
 return f'''<!doctype html><html lang="ko" data-lang="ko" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="site-home" content="https://mirinaeman.com/"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{url}"><link rel="icon" href="../../favicon.svg" type="image/svg+xml"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{og}"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1731"><meta property="og:image:height" content="909"><meta property="og:image:alt" content="{e(b['thumbnail']['alt'])}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(desc)}"><meta name="twitter:image" content="{og}"><meta name="twitter:image:alt" content="{e(b['thumbnail']['alt'])}"><script type="application/ld+json">{json.dumps(graph,ensure_ascii=False)}</script><link rel="stylesheet" href="../../styles.css"><link rel="stylesheet" href="visit.css"><script defer src="../../navigation.js"></script><script defer src="../../app.js"></script></head><body><a class="skip" href="#main">본문으로 이동</a><site-navigation data-page="archive"></site-navigation><main id="main"><section class="page-hero"><div class="wrap"><span class="eyebrow">MUSIC · IMAGE CINEMA · WEBTOON</span><h1>{e(b['title'])}</h1><div style="max-width:var(--measure)"><p>{prose(desc)}</p><p>노래 원작 · <a href="https://mirinaeman.com/profile/">미리내맨</a></p></div><div class="actions"><a class="button primary" href="{e(b['canonical_url'])}" target="_blank" rel="noopener noreferrer">노래 · 영상 · 웹툰 감상하기</a></div></div></section><section class="section"><div class="wrap"><figure><img src="assets/og.png" width="1731" height="909" alt="{e(b['thumbnail']['alt'])}" loading="lazy"></figure></div></section><section class="section"><div class="wrap visit-story" style="max-width:var(--measure)"><h2>{e(visit["heading"])}</h2><p>{prose(visit["summary"])}</p><p>제주 노릇에서 마주한 긴 갈치통구이.<br>한 접시에 다 담기지 않는 크기에 놀라고 바삭한 껍질 속 하얀 살에 다시 놀란 저녁을 노래로 담았습니다.</p><p>뚜껑을 열기 전까지 걱정했던 갈치솥밥은 한 숟갈 뒤 다른 기억이 됩니다.<br>마지막 누룽지와 빈 접시까지 한 끼의 여운이 이어집니다.</p><h2>노래와 웹툰, 이미지 시네마</h2><p>Mirinaeman의 원곡 전체에 새로 그린 수채화 원화 9장을 엮은 약 4분 9초의 이미지 시네마입니다.<br>별도 한국어 가사 자막을 켜고 끌 수 있습니다.</p><p>웹툰 8장은 읽는 사람의 속도로 이어집니다.<br>감상 페이지에는 실제 방문 영상과 사진, 노래와 가사도 함께 있습니다.</p><p>{prose(visit["perspective"])}</p><h2>노릇 찾아가기</h2><p>{e(place["name"])} · {e(place["region"])}</p><iframe class="visit-map" src="{e(place["embedUrl"])}" title="{e(place["name"])} 위치 지도" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><div class="actions"><a class="button" href="{e(place["directionsUrl"])}" target="_blank" rel="noopener noreferrer">{e(place["directionsLabel"])}</a></div><p>{prose(visit["visitNote"])}</p><div class="actions"><a class="button primary" href="{e(b['canonical_url'])}/cinema/">이미지 시네마 보기</a></div><div class="actions"><a class="button" href="https://mirinaeman.com/archive/">아카이브로</a></div></div></section></main><footer class="footer"><div class="wrap"><p>© 미리내맨 · mirinaeman.com</p></div></footer></body></html>'''
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');a=ap.parse_args();p=PROFILE/'archive'/BODY_ID/'index.html';content=render()
 content=re.sub(r'<p([^>]*)>(.*?)</p>',lambda m:'<p'+m[1]+'><span class="statement-line">'+m[2].replace('<br>','</span><span class="statement-line">')+'</span></p>',content,flags=re.S)
 if a.check:assert p.read_text()==content,'Galchi introduction drift'
 else:p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
 print('Galchi archive introduction: PASS')
